insert into public.grapes (id, name, synonyms, color, short, aromas, regions, body, acidity, tannin, food) values
  (1, 'Nebbiolo', array['Spanna', 'Chiavennasca']::text[], 'rot', 'Spät reifende Rotweinsorte aus dem Piemont. Helle Farbe, aber kräftige Tannine und hohe Säure. Braucht oft einige Jahre Flaschenreife und wird dann sehr vielschichtig.', array['Rose', 'Sauerkirsche', 'Teer', 'Veilchen', 'Lakritz', 'Trüffel']::text[], 'Barolo, Barbaresco, Roero, Valtellina, Gattinara', 4, 5, 5, 'Trüffelpasta, Schmorbraten, Wild, gereifter Hartkäse'),
  (2, 'Sangiovese', array['Brunello', 'Prugnolo Gentile', 'Morellino', 'Sangiovese Grosso', 'Nielluccio']::text[], 'rot', 'Wichtigste Rotweinsorte Italiens und Herz des Chianti. Saftige Säure, mittlere Tannine, oft mit einer leicht herben Note. Sehr guter Essensbegleiter.', array['Sauerkirsche', 'Tomatenblatt', 'Kräuter', 'Leder', 'Pflaume']::text[], 'Chianti, Montalcino, Montepulciano, Maremma, Romagna', 3, 4, 4, 'Pasta mit Tomatensauce, Pizza, Bistecca, Pecorino'),
  (3, 'Spätburgunder', array['Pinot Noir', 'Blauburgunder', 'Pinot Nero']::text[], 'rot', 'Feine, elegante Rotweinsorte mit heller Farbe und wenig Tannin. Reagiert stark auf Lage und Ausbau, deshalb sehr unterschiedliche Stile von leicht-fruchtig bis tief und komplex.', array['Erdbeere', 'Himbeere', 'Kirsche', 'Waldboden', 'Pilze']::text[], 'Burgund, Baden, Ahr, Pfalz, Südtirol, Oregon', 2, 4, 2, 'Ente, Geflügel, Lachs, Pilzgerichte, Weichkäse'),
  (4, 'Cabernet Sauvignon', array['Cabernet']::text[], 'rot', 'Weltweit verbreitete Rotweinsorte aus Bordeaux. Dunkle Farbe, kräftige Tannine, gute Lagerfähigkeit. Oft mit Merlot verschnitten.', array['Cassis', 'Zeder', 'Paprika', 'Minze', 'Tabak']::text[], 'Bordeaux (Médoc), Napa Valley, Toskana, Chile, Australien', 5, 3, 5, 'Rindersteak, Lamm, kräftige Schmorgerichte, Hartkäse'),
  (5, 'Merlot', array[]::text[], 'rot', 'Weiche, fruchtige Rotweinsorte mit runden Tanninen. In Bordeaux die meistgepflanzte Sorte, besonders am rechten Ufer.', array['Pflaume', 'Schwarzkirsche', 'Schokolade', 'Kräuter']::text[], 'Bordeaux (Pomerol, Saint-Émilion), Toskana, Tessin, Friaul', 4, 3, 3, 'Braten, Pasta mit Fleischsauce, Pilzrisotto'),
  (6, 'Syrah', array['Shiraz']::text[], 'rot', 'Dunkle, würzige Rotweinsorte von der Rhône. In kühlen Lagen pfeffrig und elegant, in warmen Regionen (als Shiraz) üppig und fruchtbetont.', array['Brombeere', 'schwarzer Pfeffer', 'Oliven', 'Speck', 'Veilchen']::text[], 'Nördliche Rhône, Südfrankreich, Barossa Valley, Südafrika', 5, 3, 4, 'Gegrilltes, Lamm, Wild, würzige Eintöpfe'),
  (7, 'Grenache', array['Garnacha', 'Garnacha Tinta', 'Grenache Noir', 'Cannonau']::text[], 'rot', 'Wärmeliebende Sorte mit viel Frucht und oft hohem Alkohol, aber wenig Farbe und Tannin. Basis vieler Weine der südlichen Rhône und Spaniens.', array['Erdbeere', 'Himbeere', 'Kräuter der Garrigue', 'weißer Pfeffer']::text[], 'Châteauneuf-du-Pape, Côtes du Rhône, Priorat, Navarra, Sardinien', 4, 2, 2, 'Gegrilltes Gemüse, Lamm, mediterrane Küche'),
  (8, 'Tempranillo', array['Tinta de Toro', 'Tinto Fino', 'Tinta Roriz', 'Aragonez', 'Tinta del País', 'Cencibel', 'Ull de Llebre']::text[], 'rot', 'Spaniens wichtigste Rotweinsorte. Mittlere Säure und Tannine, nimmt Holzausbau gut an. Bei Rioja und Ribera del Duero oft lange im Fass gereift.', array['Kirsche', 'Tabak', 'Leder', 'Vanille', 'Dill']::text[], 'Rioja, Ribera del Duero, Toro, Douro', 4, 3, 4, 'Lamm, Chorizo, Manchego, Tapas'),
  (9, 'Montepulciano', array[]::text[], 'rot', 'Ertragreiche Rotweinsorte aus Mittelitalien mit dunkler Farbe, weichen Tanninen und viel Frucht. Nicht zu verwechseln mit dem Ort Montepulciano in der Toskana.', array['Schwarzkirsche', 'Pflaume', 'Kräuter', 'Lakritz']::text[], 'Abruzzen, Marken (Rosso Conero)', 4, 3, 3, 'Pizza, Pasta, Grillfleisch'),
  (10, 'Primitivo', array['Zinfandel']::text[], 'rot', 'Fruchtbetonte, oft alkoholreiche Rotweinsorte aus Apulien, genetisch identisch mit dem kalifornischen Zinfandel. Weiche Tannine, teils leichte Restsüße.', array['Brombeere', 'Rosinen', 'Marmelade', 'Gewürze']::text[], 'Apulien (Manduria), Kalifornien', 5, 2, 3, 'Grillfleisch, Burger, Pasta mit Ragù'),
  (11, 'Blaufränkisch', array['Lemberger', 'Kékfrankos']::text[], 'rot', 'Mitteleuropäische Rotweinsorte mit lebendiger Säure und würziger Frucht. Im Burgenland und in Württemberg zu Hause.', array['Brombeere', 'Kirsche', 'Pfeffer', 'Graphit']::text[], 'Burgenland, Württemberg, Ungarn', 3, 4, 3, 'Ente, Gulasch, Wild, Hartkäse'),
  (12, 'Zweigelt', array['Blauer Zweigelt', 'Rotburger']::text[], 'rot', 'Häufigste Rotweinsorte Österreichs, eine Kreuzung aus Blaufränkisch und St. Laurent. Saftig und kirschfruchtig, meist unkompliziert.', array['Sauerkirsche', 'Weichsel', 'Zimt']::text[], 'Niederösterreich, Burgenland', 3, 3, 2, 'Schweinebraten, Brettljause, Pasta'),
  (13, 'Malbec', array['Côt', 'Auxerrois (Cahors)']::text[], 'rot', 'Ursprünglich aus Südwestfrankreich, heute vor allem in Argentinien berühmt. Dunkel, fruchtig, mit samtigen Tanninen.', array['Pflaume', 'Brombeere', 'Veilchen', 'Kakao']::text[], 'Mendoza, Cahors', 4, 3, 4, 'Steak vom Grill, Empanadas'),
  (14, 'Gamay', array['Gamay Noir']::text[], 'rot', 'Leichte, fruchtige Rotweinsorte des Beaujolais. Wenig Tannin, frische Säure, wird gern leicht gekühlt getrunken.', array['Himbeere', 'Kirsche', 'Banane', 'Veilchen']::text[], 'Beaujolais, Loire', 2, 4, 1, 'Charcuterie, Geflügel, Flammkuchen'),
  (20, 'Riesling', array['Weißer Riesling', 'Rheinriesling']::text[], 'weiss', 'Deutschlands Paradesorte. Hohe Säure, ausgeprägte Frucht und große Bandbreite von knochentrocken bis edelsüß. Kann Jahrzehnte reifen.', array['Pfirsich', 'Apfel', 'Zitrus', 'Schiefer', 'Petrol (gereift)']::text[], 'Mosel, Rheingau, Pfalz, Nahe, Wachau, Elsass', 2, 5, null, 'Fisch, Asiatisch, Schweinebraten, Sauerkraut'),
  (21, 'Grüner Veltliner', array['Weißgipfler']::text[], 'weiss', 'Österreichs wichtigste Weißweinsorte. Frisch und würzig mit dem typischen „Pfefferl“. Von leichtem Heurigenwein bis zu kräftigen Lagenweinen.', array['grüner Apfel', 'weißer Pfeffer', 'Zitrus', 'Linsen']::text[], 'Wachau, Kamptal, Kremstal, Weinviertel', 3, 4, null, 'Wiener Schnitzel, Spargel, asiatische Küche'),
  (22, 'Chardonnay', array['Morillon']::text[], 'weiss', 'Vielseitige Weißweinsorte, die den Stil stark vom Ausbau annimmt: von schlank und mineralisch (Chablis) bis cremig und holzbetont.', array['Apfel', 'Melone', 'Butter', 'Haselnuss', 'Vanille']::text[], 'Burgund, Chablis, Champagne, Kalifornien, Südsteiermark', 4, 3, null, 'Geflügel in Rahmsauce, Hummer, Risotto'),
  (23, 'Sauvignon Blanc', array['Muskat-Sylvaner', 'Fumé Blanc']::text[], 'weiss', 'Aromatische Weißweinsorte mit knackiger Säure und grünen, frischen Noten. Klassisch von der Loire, berühmt aus Neuseeland und der Steiermark.', array['Stachelbeere', 'Holunderblüte', 'grüne Paprika', 'Grapefruit']::text[], 'Loire (Sancerre), Bordeaux, Steiermark, Marlborough', 2, 5, null, 'Ziegenkäse, Spargel, Salate, Meeresfrüchte'),
  (24, 'Grauburgunder', array['Pinot Grigio', 'Pinot Gris', 'Ruländer']::text[], 'weiss', 'Weißweinsorte mit zwei Gesichtern: als Pinot Grigio leicht und neutral, als Grauburgunder aus Baden oder dem Elsass voller und würziger.', array['Birne', 'Mandel', 'Honigmelone', 'Nuss']::text[], 'Baden, Pfalz, Elsass, Friaul, Südtirol', 3, 3, null, 'Kalbfleisch, Pasta mit Gemüse, Pilze'),
  (25, 'Weißburgunder', array['Pinot Blanc', 'Pinot Bianco', 'Weissburgunder', 'Klevner']::text[], 'weiss', 'Dezente, elegante Weißweinsorte mit milder Säure. Unaufdringlich und ein sehr guter Essensbegleiter.', array['Birne', 'Apfel', 'Mandel', 'Blüten']::text[], 'Baden, Pfalz, Südtirol, Burgenland', 3, 3, null, 'Spargel, Fisch, Kalbfleisch'),
  (26, 'Silvaner', array['Grüner Silvaner', 'Sylvaner']::text[], 'weiss', 'Traditionelle Sorte Frankens mit zurückhaltender Frucht, erdigen Noten und milder Säure. Klassisch im Bocksbeutel.', array['grüner Apfel', 'Heu', 'Kräuter', 'Feuerstein']::text[], 'Franken, Rheinhessen, Elsass', 2, 3, null, 'Spargel, Süßwasserfisch, fränkische Brotzeit'),
  (27, 'Müller-Thurgau', array['Rivaner']::text[], 'weiss', 'Unkomplizierte, früh trinkreife Weißweinsorte mit milder Säure und leichter Muskatnote.', array['Pfirsich', 'Muskat', 'Zitrus']::text[], 'Rheinhessen, Baden, Franken, Südtirol', 2, 2, null, 'Leichte Küche, Salate, Zwiebelkuchen'),
  (28, 'Gewürztraminer', array['Traminer']::text[], 'weiss', 'Sehr aromatische Weißweinsorte mit Rosenduft und Litschi, oft wenig Säure und etwas Restsüße.', array['Rose', 'Litschi', 'Ingwer', 'Orangenschale']::text[], 'Elsass, Südtirol, Pfalz', 4, 2, null, 'Asiatische Küche, Münsterkäse, Gänseleber'),
  (29, 'Chenin Blanc', array['Steen']::text[], 'weiss', 'Vielseitige Weißweinsorte der Loire mit hoher Säure, von trocken über süß bis schäumend.', array['Quitte', 'Honig', 'Apfel', 'Wachs']::text[], 'Loire (Vouvray, Savennières), Südafrika', 3, 5, null, 'Schweinefleisch, Geflügel, Fisch mit Sauce'),
  (30, 'Vermentino', array['Rolle', 'Rollo', 'Pigato', 'Favorita']::text[], 'weiss', 'Mediterrane Weißweinsorte mit frischer Säure, Zitrus und leicht salziger Note.', array['Zitrone', 'Kräuter', 'Mandel', 'Meeresbrise']::text[], 'Sardinien, Ligurien, Toskana, Provence', 2, 4, null, 'Fisch, Meeresfrüchte, Pesto'),
  (31, 'Albariño', array['Alvarinho']::text[], 'weiss', 'Frische, aromatische Weißweinsorte aus Nordwestspanien mit salziger Mineralität.', array['Pfirsich', 'Zitrus', 'Aprikose', 'Salz']::text[], 'Rías Baixas, Vinho Verde', 2, 4, null, 'Meeresfrüchte, gegrillter Fisch, Pulpo'),
  (32, 'Glera', array['Prosecco']::text[], 'weiss', 'Die Rebsorte hinter dem Prosecco. Leicht, blumig und fruchtig, meist als Schaumwein ausgebaut.', array['grüner Apfel', 'Birne', 'Akazienblüte']::text[], 'Venetien, Friaul', 1, 3, null, 'Aperitif, Antipasti'),
  (40, 'Cabernet Franc', array['Bouchet', 'Breton']::text[], 'rot', 'Elternsorte des Cabernet Sauvignon, etwas leichter und duftiger. Sortenrein vor allem an der Loire, in Bordeaux wichtiger Verschnittpartner.', array['Himbeere', 'Veilchen', 'grüne Paprika', 'Graphit']::text[], 'Loire (Chinon, Bourgueil), Saint-Émilion, Friaul, Toskana', 3, 4, 3, 'Kalb, Schweinebraten, Ziegenkäse, gegrilltes Gemüse'),
  (41, 'Touriga Nacional', array[]::text[], 'rot', 'Portugals Spitzensorte, Rückgrat von Portwein und kräftigen Douro-Rotweinen. Dunkel, blumig, mit festem Tannin.', array['Veilchen', 'Brombeere', 'Bergamotte', 'Kräuter']::text[], 'Douro, Dão', 5, 3, 5, 'Lamm, Wild, gereifter Käse'),
  (42, 'Mourvèdre', array['Monastrell', 'Mataro', 'Mourvedre']::text[], 'rot', 'Spät reifende, wärmeliebende Sorte mit dunkler Frucht und erdig-wilden Noten. Teil der klassischen GSM-Cuvée mit Grenache und Syrah.', array['Brombeere', 'Pfeffer', 'Leder', 'Wildkräuter']::text[], 'Bandol, südliche Rhône, Jumilla, Yecla', 5, 3, 5, 'Lamm, Wild, Eintöpfe, Grillfleisch'),
  (43, 'Petit Verdot', array[]::text[], 'rot', 'Tiefdunkle Bordeaux-Sorte, meist in kleinen Anteilen für Farbe, Würze und Tannin. Sortenrein selten.', array['Veilchen', 'Brombeere', 'Lakritz', 'Salbei']::text[], 'Bordeaux, Spanien, Australien, Kalifornien', 5, 3, 5, 'Rind, Wild, kräftige Schmorgerichte'),
  (44, 'Corvina', array['Corvina Veronese', 'Corvinone']::text[], 'rot', 'Hauptsorte von Valpolicella und Amarone. Frisch und kirschig, getrocknet (Appassimento) wird sie konzentriert und rosinig.', array['Sauerkirsche', 'Mandel', 'Rosinen (Amarone)', 'Kräuter']::text[], 'Valpolicella, Bardolino', 3, 4, 3, 'Risotto, Pasta, beim Amarone gereifter Käse und Schmorbraten'),
  (45, 'Touriga Franca', array['Touriga Francesa']::text[], 'rot', 'Meistgepflanzte Sorte im Douro, duftig und fruchtig. Fast immer im Verschnitt mit Touriga Nacional.', array['Brombeere', 'Rose', 'Kirsche']::text[], 'Douro', 4, 3, 4, 'Grillfleisch, Bacalhau, Hartkäse'),
  (46, 'Rondinella', array[]::text[], 'rot', 'Verschnittpartner der Corvina im Valpolicella. Bringt Farbe und Kräuterwürze.', array['Kirsche', 'Kräuter', 'Pfeffer']::text[], 'Valpolicella, Bardolino', 3, 3, 3, 'Pasta, helles Fleisch'),
  (47, 'Carménère', array['Carmenère', 'Carmenere', 'Grande Vidure']::text[], 'rot', 'Alte Bordeaux-Sorte, heute das Aushängeschild Chiles. Weich, dunkelfruchtig, mit typisch grüner Paprikanote.', array['Brombeere', 'grüne Paprika', 'Pfeffer', 'Schokolade']::text[], 'Chile (Colchagua, Maipo)', 4, 3, 3, 'Grillfleisch, Chili con Carne, Empanadas'),
  (48, 'Carignan', array['Cariñena', 'Mazuelo', 'Carignano', 'Samsó']::text[], 'rot', 'Mediterrane Sorte mit hoher Säure und kräftigem Tannin. Von alten Reben ausdrucksstark und würzig.', array['Sauerkirsche', 'Pflaume', 'Kräuter', 'Lakritz']::text[], 'Languedoc, Priorat, Sardinien, Rioja', 4, 4, 4, 'Cassoulet, Wurst, Grillgemüse'),
  (49, 'Cinsault', array['Cinsaut']::text[], 'rot', 'Leichte, duftige Sorte aus Südfrankreich, wichtig für Rosé. Elternteil des Pinotage.', array['Erdbeere', 'Kirsche', 'Blüten']::text[], 'Provence, Languedoc, Libanon, Südafrika', 2, 3, 2, 'Mediterrane Küche, Grillgemüse, Salate'),
  (50, 'Schwarzriesling', array['Pinot Meunier', 'Meunier', 'Müllerrebe']::text[], 'rot', 'Burgunder-Spielart, in der Champagne eine der drei Hauptsorten, in Württemberg als fruchtiger Rotwein beliebt.', array['Kirsche', 'Himbeere', 'Brot']::text[], 'Champagne, Württemberg', 2, 4, 2, 'Vesper, Geflügel, Flammkuchen'),
  (51, 'Barbera', array[]::text[], 'rot', 'Piemonteser Alltagsliebling mit kräftiger Säure und wenig Tannin. Saftig und unkompliziert, im Barrique auch ernsthaft.', array['Sauerkirsche', 'Pflaume', 'Lakritz']::text[], 'Asti, Alba, Monferrato, Oltrepò Pavese', 3, 5, 2, 'Pizza, Pasta, Salami, Vitello tonnato'),
  (52, 'Petite Sirah', array['Durif']::text[], 'rot', 'Kreuzung aus Syrah und Peloursin, tintig dunkel mit viel Tannin. Vor allem in Kalifornien verbreitet.', array['Heidelbeere', 'Pflaume', 'schwarzer Pfeffer']::text[], 'Kalifornien, Australien', 5, 3, 5, 'BBQ, Spareribs, kräftiges Fleisch'),
  (53, 'Tinta Barroca', array[]::text[], 'rot', 'Früh reifende Douro-Sorte für Port und Rotwein, weich und vollmundig.', array['Brombeere', 'Kirsche', 'Pflaume']::text[], 'Douro', 4, 2, 3, 'Schmorgerichte, Käse'),
  (54, 'Alicante Bouschet', array['Garnacha Tintorera']::text[], 'rot', 'Färbertraube mit rotem Fruchtfleisch. Sehr dunkle, kräftige Weine, im Alentejo besonders geschätzt.', array['Brombeere', 'Pflaume', 'Schokolade']::text[], 'Alentejo, Spanien, Südfrankreich', 5, 3, 4, 'Grillfleisch, Eintöpfe'),
  (55, 'Tannat', array['Harriague']::text[], 'rot', 'Eine der tanninreichsten Sorten überhaupt. Aus Madiran sehr kräftig, aus Uruguay oft zugänglicher.', array['Brombeere', 'Pflaume', 'Rauch', 'Kakao']::text[], 'Madiran, Uruguay', 5, 4, 5, 'Entenconfit, Steak, Cassoulet'),
  (56, 'Nero d''Avola', array['Calabrese']::text[], 'rot', 'Wichtigste Rotweinsorte Siziliens. Dunkle Frucht, weiche Tannine, gute Säure.', array['Schwarzkirsche', 'Pflaume', 'Lakritz', 'Pfeffer']::text[], 'Sizilien', 4, 3, 3, 'Pasta alla Norma, Grillfleisch, Pizza'),
  (57, 'Pinotage', array[]::text[], 'rot', 'Südafrikanische Kreuzung aus Spätburgunder und Cinsault. Fruchtig, rauchig, teils mit Kaffeenote.', array['Pflaume', 'Brombeere', 'Rauch', 'Kaffee']::text[], 'Südafrika (Stellenbosch, Swartland)', 4, 3, 3, 'Braai, Burger, Wurst'),
  (58, 'Negroamaro', array[]::text[], 'rot', 'Apulische Sorte mit dunkler Frucht und leicht bitterer Note, oft mit Malvasia Nera verschnitten. Auch als Rosé beliebt.', array['Pflaume', 'Schwarzkirsche', 'Tabak', 'Kräuter']::text[], 'Salento (Apulien)', 4, 3, 3, 'Orecchiette mit Ragù, Lamm, Auberginen'),
  (59, 'Dolcetto', array[]::text[], 'rot', 'Unkomplizierter Piemonteser für jeden Tag: fruchtig, weich, mit leicht bitterem Mandelton.', array['Kirsche', 'Pflaume', 'Mandel']::text[], 'Alba, Dogliani, Diano d''Alba', 3, 2, 3, 'Antipasti, Pasta, Salami'),
  (60, 'Molinara', array[]::text[], 'rot', 'Helle, säurebetonte Sorte, kleiner Anteil in Valpolicella und Bardolino.', array['Kirsche', 'Kräuter']::text[], 'Valpolicella, Bardolino', 2, 4, 2, 'Pasta, helles Fleisch'),
  (61, 'Tinto Cão', array[]::text[], 'rot', 'Alte Douro-Sorte mit wenig Ertrag, bringt Eleganz und Lagerfähigkeit in Verschnitte.', array['Kirsche', 'Blüten', 'Gewürze']::text[], 'Douro, Dão', 3, 4, 3, 'Geflügel, Schwein'),
  (62, 'Trincadeira', array['Tinta Amarela']::text[], 'rot', 'Portugiesische Sorte mit würzig-kräutriger Frucht, vor allem im Alentejo.', array['Pflaume', 'Kräuter', 'Pfeffer']::text[], 'Alentejo, Douro', 3, 4, 3, 'Schwein, Würste, Eintöpfe'),
  (63, 'Castelão', array['Periquita', 'João de Santarém']::text[], 'rot', 'Weit verbreitete Sorte im Süden Portugals, fruchtig mit wilder Note.', array['Johannisbeere', 'Pflaume', 'Rauch']::text[], 'Setúbal, Tejo, Alentejo', 3, 3, 3, 'Grillfleisch, Bacalhau'),
  (64, 'Aglianico', array[]::text[], 'rot', 'Der „Barolo des Südens": kraftvoll, säure- und tanninreich, lange lagerfähig.', array['Schwarzkirsche', 'Leder', 'Tabak', 'Rauch']::text[], 'Taurasi (Kampanien), Vulture (Basilikata)', 5, 4, 5, 'Lamm, Wild, Schmorbraten'),
  (65, 'Graciano', array['Morrastel', 'Tintilla']::text[], 'rot', 'Duftige, säurereiche Sorte aus der Rioja, meist im Verschnitt mit Tempranillo für Frische und Lagerfähigkeit.', array['Veilchen', 'Brombeere', 'Kräuter']::text[], 'Rioja, Navarra', 4, 4, 4, 'Lamm, Chorizo'),
  (66, 'Lambrusco', array['Lambrusco Grasparossa', 'Lambrusco di Sorbara', 'Lambrusco Salamino']::text[], 'rot', 'Familie roter Sorten aus der Emilia für spritzige, oft trockene Rotweine. Viel besser als ihr Ruf.', array['Erdbeere', 'Kirsche', 'Veilchen']::text[], 'Emilia-Romagna (Modena, Reggio Emilia)', 2, 4, 2, 'Mortadella, Parmaschinken, Pizza, Tortellini'),
  (67, 'Refosco', array['Refosco dal Peduncolo Rosso', 'Teran']::text[], 'rot', 'Rote Sorte aus Friaul mit kräftiger Säure und leicht bitterer Note.', array['Brombeere', 'Pflaume', 'Mandel']::text[], 'Friaul, Slowenien, Istrien', 3, 4, 3, 'Wurst, Wild, deftige Küche'),
  (68, 'Lagrein', array[]::text[], 'rot', 'Südtiroler Spezialität: tiefdunkel, samtig, mit Veilchen- und Kakaonoten. Auch als Rosé (Kretzer).', array['Veilchen', 'Brombeere', 'Kakao', 'Kräuter']::text[], 'Südtirol, Trentino', 4, 3, 3, 'Speck, Wild, Gulasch'),
  (69, 'Canaiolo', array['Canaiolo Nero']::text[], 'rot', 'Traditioneller Verschnittpartner des Sangiovese im Chianti, macht die Weine weicher.', array['Kirsche', 'Veilchen']::text[], 'Toskana', 3, 3, 2, 'Toskanische Küche'),
  (70, 'Mencía', array['Mencia', 'Jaen']::text[], 'rot', 'Nordwestspanische Sorte mit frischer, kräutriger Frucht und mineralischen Noten. Gilt als Entdeckung der letzten Jahre.', array['Himbeere', 'Kirsche', 'Kräuter', 'Graphit']::text[], 'Bierzo, Ribeira Sacra, Dão', 3, 4, 3, 'Geflügel, Schwein, Pulpo'),
  (71, 'Bonarda', array[]::text[], 'rot', 'Name für verschiedene Sorten: in Argentinien eine weiche, fruchtige Rotweinsorte, in Norditalien meist Croatina.', array['Pflaume', 'Kirsche', 'Veilchen']::text[], 'Mendoza, Oltrepò Pavese', 3, 3, 3, 'Pizza, Grillfleisch, Pasta'),
  (72, 'St. Laurent', array['Sankt Laurent', 'Saint Laurent', 'Svatovavřinecké']::text[], 'rot', 'Burgunderähnliche Sorte aus Österreich, samtig mit dunkler Kirschfrucht.', array['Sauerkirsche', 'Brombeere', 'Waldboden']::text[], 'Thermenregion, Burgenland, Pfalz', 3, 3, 2, 'Ente, Wild, Pilze'),
  (73, 'Saperavi', array[]::text[], 'rot', 'Georgiens wichtigste Rotweinsorte, Färbertraube mit sehr dunkler Farbe und lebendiger Säure.', array['Brombeere', 'Pflaume', 'Gewürze']::text[], 'Kachetien (Georgien)', 5, 4, 4, 'Grillspieße, Lamm, Walnussgerichte'),
  (74, 'Nerello Mascalese', array[]::text[], 'rot', 'Sorte vom Ätna: hell, elegant und mineralisch, wird oft mit Burgunder verglichen.', array['Kirsche', 'Himbeere', 'Vulkangestein', 'Kräuter']::text[], 'Etna (Sizilien)', 3, 4, 3, 'Thunfisch, Geflügel, Pasta'),
